import { reportSheetMatches, type ReportSheetKind } from './reportSheetMatches'

export const TRIM_THRESHOLD_BYTES = 4_000_000
// Vercel's body limit includes multipart boundaries, field values and headers.
export const MAX_REPORT_UPLOAD_BYTES = 4_500_000 - 64 * 1024

export class ReportUploadError extends Error {}

/** Repack only ZIPs generated by SheetJS here (stored entries, no ZIP64/descriptors).
 * Native deflate compresses large report XML much better than SheetJS's JS compressor.
 * XML bytes and their CRCs are unchanged; only ZIP sizes, methods and offsets change.
 */
export async function compressStoredZip(bytes: ArrayBuffer): Promise<ArrayBuffer | null> {
  if (typeof CompressionStream === 'undefined') return null
  try { new CompressionStream('deflate-raw') } catch { return null }
  const input = new Uint8Array(bytes)
  const view = new DataView(bytes)
  const end = input.length - 22
  if (end < 0 || view.getUint32(end, true) !== 0x06054b50 || view.getUint16(end + 20, true) !== 0) throw new Error('Invalid generated ZIP')
  if (view.getUint32(end + 4, true) !== 0 || view.getUint16(end + 8, true) !== view.getUint16(end + 10, true)) throw new Error('Unsupported generated ZIP')
  const count = view.getUint16(end + 10, true)
  let cursor = view.getUint32(end + 16, true)
  const locals: Uint8Array<ArrayBuffer>[] = []
  const directory: Uint8Array<ArrayBuffer>[] = []
  let offset = 0
  for (let index = 0; index < count; index++) {
    if (view.getUint32(cursor, true) !== 0x02014b50 || view.getUint16(cursor + 10, true) !== 0 || (view.getUint16(cursor + 8, true) & 8)) throw new Error('Expected stored ZIP entry')
    const localOffset = view.getUint32(cursor + 42, true)
    if (view.getUint32(localOffset, true) !== 0x04034b50) throw new Error('Invalid local ZIP entry')
    const size = view.getUint32(cursor + 24, true)
    const headerEnd = localOffset + 30 + view.getUint16(localOffset + 26, true) + view.getUint16(localOffset + 28, true)
    const data = input.slice(headerEnd, headerEnd + size)
    if (data.length !== size) throw new Error('Truncated ZIP entry')
    const compressed = new Uint8Array(await new Response(new Blob([data]).stream().pipeThrough(new CompressionStream('deflate-raw'))).arrayBuffer())
    // Store incompressible entries unchanged rather than making them larger.
    const useDeflate = compressed.length < data.length
    const body = useDeflate ? compressed : data
    const local = input.slice(localOffset, headerEnd)
    const localView = new DataView(local.buffer)
    localView.setUint16(8, useDeflate ? 8 : 0, true)
    localView.setUint32(18, body.length, true)
    const directoryEnd = cursor + 46 + view.getUint16(cursor + 28, true) + view.getUint16(cursor + 30, true) + view.getUint16(cursor + 32, true)
    const central = input.slice(cursor, directoryEnd)
    const centralView = new DataView(central.buffer)
    centralView.setUint16(10, useDeflate ? 8 : 0, true)
    centralView.setUint32(20, body.length, true)
    centralView.setUint32(42, offset, true)
    locals.push(local, body)
    directory.push(central)
    offset += local.length + body.length
    cursor = directoryEnd
  }
  if (cursor !== end) throw new Error('Invalid ZIP directory boundary')
  const footer = input.slice(end)
  const footerView = new DataView(footer.buffer)
  footerView.setUint32(12, directory.reduce((sum, entry) => sum + entry.length, 0), true)
  footerView.setUint32(16, offset, true)
  return new Blob([...locals, ...directory, footer]).arrayBuffer()
}

/** No formulas are evaluated: cached values and the selected sheet objects are retained. */
export async function uploadTrim(file: File, keepSheet: (name: string) => boolean): Promise<File> {
  if (file.size <= TRIM_THRESHOLD_BYTES) return file
  const XLSX = await import('xlsx')
  const workbook = XLSX.read(await file.arrayBuffer(), { type: 'array', cellNF: true, cellDates: false })
  const names = workbook.SheetNames.filter(keepSheet)
  // Preserve server-side missing-sheet diagnostics (when the original fits the body limit).
  if (names.length === 0) return file
  const trimmed = XLSX.utils.book_new()
  trimmed.Workbook = { WBProps: { ...workbook.Workbook?.WBProps } }
  for (const name of names) XLSX.utils.book_append_sheet(trimmed, workbook.Sheets[name], name)
  let bytes: ArrayBuffer = XLSX.write(trimmed, { type: 'array', bookType: 'xlsx', compression: true })
  if (bytes.byteLength > MAX_REPORT_UPLOAD_BYTES) {
    const stored: ArrayBuffer = XLSX.write(trimmed, { type: 'array', bookType: 'xlsx', compression: false })
    const native = await compressStoredZip(stored)
    if (native && native.byteLength < bytes.byteLength) bytes = native
  }
  return new File([bytes], file.name, { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', lastModified: file.lastModified })
}

/** Run once before preview; retain the returned File in state for file-based confirmation. */
export async function prepareReportUpload(file: File, kind: ReportSheetKind): Promise<File> {
  let upload: File
  try {
    upload = await uploadTrim(file, name => reportSheetMatches(name, kind))
  } catch {
    throw new ReportUploadError('Không thể đọc file Excel. Vui lòng kiểm tra file rồi thử lại.')
  }
  if (upload.size > MAX_REPORT_UPLOAD_BYTES) {
    const sheet = kind === 'PACKING' ? 'ĐÓNG GÓI' : kind
    throw new ReportUploadError(`File quá lớn để tải lên (${(upload.size / 1_000_000).toFixed(2)} MB). Hãy lưu file chỉ giữ sheet ${sheet} rồi thử lại.`)
  }
  return upload
}
